def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D table to store the results of subproblems
    table = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Check if the current item's price is less than or equal to the current budget
            if items[i - 1][0] <= j:
                # Update the table with the maximum of the two values:
                # 1. The value of the current item plus the value of the previous item
                # 2. The value of the previous item
                table[i][j] = max(table[i - 1][j - items[i - 1][0]] + items[i - 1][1], table[i - 1][j])
            else:
                # Update the table with the value of the previous item
                table[i][j] = table[i - 1][j]

    # Return the maximum value in the last row of the table
    return max(table[-1])
