def calculate_arrangements(n, m, a):
    # Initialize a 2D array dp with 0s
    dp = [[0 for _ in range(m+1)] for _ in range(n+1)]

    # Initialize the first row with 1s
    for i in range(m+1):
        dp[0][i] = 1

    # Fill in the table
    for i in range(1, n+1):
        for j in range(1, m+1):
            for k in range(a[i-1]+1):
                if j >= k:
                    dp[i][j] += dp[i-1][j-k]

    # Return the last entry of the last row
    return dp[n][m] % (10**6 + 7)
